def figure_svg(kind: str) -> str:
    if kind in LEGACY_FIGURES:
        return LEGACY_FIGURES[kind]
    if kind in ADDITIONAL_FIGURES:
        return ADDITIONAL_FIGURES[kind]
    return procedural_figure_svg(kind)


def figure_bytes(kind: str) -> bytes:
    return figure_svg(kind).encode('utf8')


def figure_digest(kind: str) -> str:
    return hashlib.sha256(figure_bytes(kind)).hexdigest()


def export_many(kinds: list[str], output_dir: Path) -> dict[str, str]:
    output_dir.mkdir(parents=True, exist_ok=True)
    result = {}
    for kind in sorted(dict.fromkeys(kinds)):
        path = output_dir / f'{kind}.svg'
        path.write_bytes(figure_bytes(kind))
        result[kind] = str(path)
    return result


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description='Materialize companion-slide figure SVGs.')
    parser.add_argument('--output-dir', required=True)
    parser.add_argument('kinds', nargs='*')
    args = parser.parse_args(argv)
    mapping = export_many(args.kinds, Path(args.output_dir))
    print(json.dumps(mapping, sort_keys=True))
    return 0


if __name__ == '__main__':  # pragma: no cover
    raise SystemExit(main())
